      this.coins = []; this.enemies = []; this.stars = []; this.props = [];
      this.movers = []; this.blinkers = []; this.items = []; this.talkers = []; this.waters = []; this.falls = [];
      this.life = []; this.anims = []; this.scatterPts = [];
