      const m = { b, base: [cx, cy, cz], half: [sx / 2, sy / 2, sz / 2], fn, off: [0, 0, 0], vel: [0, 0, 0], mesh: build((g) => box(g, I4, sx, sy, sz, col)) };
      b.mover = m;
