      c.fillStyle = '#fff'; c.beginPath(); c.moveTo(w * .02, h); c.lineTo(w * .45, h * .16); c.lineTo(w * .98, h); c.fill();
      c.fillStyle = '#c6dcf5'; c.beginPath(); c.moveTo(w * .45, h * .16); c.lineTo(w * .98, h); c.lineTo(w * .5, h); c.fill();
