  const PLAYABLE = CATS.map((c, i) => (c.id === 'sphinx' || c.id === 'kappi' ? i : -1)).filter((i) => i >= 0);
  let catIdx = PLAYABLE.find((i) => CATS[i].id === 'kappi') ?? PLAYABLE[0] ?? 0;
