          const d = [Math.sin(th) * Math.sin(ph), Math.cos(th), Math.sin(th) * Math.cos(ph)];
          if (d[2] > 0.55 && d[1] < 0.75) continue;                               // Gesicht frei lassen
          cyl(g, M4.from(d[0] * 0.74, 0.78 + d[1] * 0.68, d[2] * 0.74, ph, th), 0.17, 0, 0.5, 5, hex('#f4ecd8'));
