      box(g, M4.mul(m, M4.from(0, -0.2, 0)), 0.22, 0.5, 0.36, IRON);
      cyl(g, M4.mul(m, M4.from(0, 0.05, 0.08)), 0.1, 0.16, 0.3, 6, hex('#3a3a44'));
