    const a = [0, -0.475, 0], b = [0.55, -0.475, 0], c2 = [0.55, 0.475, 0], d = [0, 0.475, 0], w = hex('#ffffff');
    g.quad(a, b, c2, d, w); g.quad(b, a, d, c2, w);
