        let m = M4.from(x, y, z, 0.35);   // weht grob nach +x (leicht schraeg)
        for (let j = 0; j <= i; j++) {
          m = M4.mul(m, M4.from(j ? 0.55 : 0.08, 0, 0, Math.sin(t * 5.5 + ph - j * 0.9) * (0.18 + j * 0.1), 0, 0, 1, 1 - j * 0.12, 1));
        }
