    L.solid(MX - 2.9, 1.2, MZ - 2.9, MX + 2.9, 9.7, MZ + 2.9, 'mill');
    cyl(g, M4.from(MX, 9.7, MZ), 2.8, 0, 2.2, 12, hex('#8a4a2a'));
