    L.block(WX + 6.5, WY + 4, WZ + 4.1, 17, 6, 0.8, HULL, 'hull');
    L.block(WX - 3.5, WY + 5.75, WZ + 4.1, 3, 2.5, 0.8, HULL, 'hull');                  // ueber dem Leck
    L.block(WX - 14.6, WY + 4, WZ, 0.8, 6, 9, HULL, 'hull');                            // Heck
