    g.quad([43.5, 5.3, 37.5], [54.5, 5.3, 37.5], [54.5, 7.4, 32], [43.5, 7.4, 32], hex('#c8402a'));
    g.quad([54.5, 5.3, 26.5], [43.5, 5.3, 26.5], [43.5, 7.4, 32], [54.5, 7.4, 32], hex('#a8301f'));
