      for (let k = 0; k < 3; k++) box(g, M4.from(x + Math.sin(k * 2) * 0.15, -7 + h * (k + 0.5) / 3, z, r() * TAU, 0, (r() - 0.5) * 0.4), 0.3, h / 3 + 0.1, 0.06, shade(hex('#4a9a3a'), 0.8 + r() * 0.4));
