    const ball = L.solid(-2.2, 0, -28.2, 2.2, 2.1, -23.8, 'bouncy'); ball.bounce = 100;
    // Teddy (beklettern!), Wachsmalstifte, Schaukelpferd, Bauklotz-Burg
