  function makeShyGhost(cx, cy, cz, rad = 4, w = 0.5, ph = 0, o = {}) {
    return Object.assign(makeGhost(cx, cy, cz, rad, w, ph), { shy: true, hide: 1, vel: [0, 0, 0], leash: o.leash ?? 22, chase: o.chase ?? 3.6, minY: o.minY ?? 0.3 });
  }
