  // Unterkante von b ueber (x, z) - Gelaende hat keine, ausser duennen Flaechen (Rodelbahn, schwebende Insel)
  const bottomAt = (b, x, z) => (b.hf ? (b.hf.overlay ? b.hf.h(x, z) - b.hf.thick : -Infinity) : b.min[1]);
