    if (e.state === 'gone') { e.t -= dt; if (e.t <= 0) e.state = 'float'; return; }
    const a = e.ph + time * e.w;
    e.pos = [e.c[0] + Math.cos(a) * e.rad, e.c[1] + Math.sin(time * 1.7 + e.ph) * 0.4, e.c[2] + Math.sin(a) * e.rad];
