    if (gy > -Infinity && e.pos[1] < gy + 0.45 * e.s) { e.pos[1] = gy + 0.45 * e.s; e.vel[1] = Math.max(0, e.vel[1]); }
    e.face = Math.atan2(p[0] - e.pos[0], p[2] - e.pos[2]);
    if (e.inv > 0 || pl.dead) return;
