    const NO_RTC = 'Dein Browser hat WebRTC abgeschaltet (z. B. Tor-/Mullvad-Browser, LibreWolf, strenger Datenschutz-Modus) – damit geht der Mehrspieler nicht.';
    const ANGLE = POSE_KEYS.map((k) => k === 'yaw');
