    let retry = 0, retryTimer = 0, gen = 0, lastSt = null, lastIce = '', pvp = true;
    const lastHitAt = new Map();                   // Angreifer: Mitspieler-id -> Zeit des letzten Treffers (kein Dauerfeuer)
