      if (!Array.isArray(m.p) || !m.p.every(isNum)) return null;
      if (m.p.length === POSE_KEYS.length - MOUTH_KEYS) m.p = m.p.concat(PL_MOUTH.rest);   // aeltere Version ohne Mund
