      const ph = pl.swimPh, stroke = clamp(1 - (clock - pl.strokeT) / 0.55, 0, 1);
      const tA = -1.35 + Math.sin(ph) * 0.35, tOut = 0.95 + Math.cos(ph) * 0.35;
      const sK = 0.5 + 0.5 * Math.sin(ph - stroke * 3);
