      armL = lerp(tA, bA, swim01); armR = lerp(-1.35 - Math.sin(ph) * 0.35, bA, swim01); armOut = lerp(tOut, bOut, swim01);
      legL = Math.sin(ph * (1.2 + swim01)) * (0.35 + swim01 * 0.15); legR = -legL;
